//! Round 36 regressions found by differential probing against `php 8.5.12`
//! (`/opt/homebrew/bin/php`, `php -r`, `LC_ALL=C TZ=UTC`). Expected strings are
//! the reference's recorded stdout, generated by running each snippet through
//! it; no PHP is needed to run them.

use phplang::eval_capture;

fn run(src: &str) -> String {
    eval_capture(src).unwrap_or_else(|e| panic!("eval error for {src:?}: {e}"))
}

#[test]
fn str_replace_matches_a_stray_byte_inside_a_character() {
    let src = r##"<?php echo bin2hex(str_replace("\xA9", "X", "é")), " ", bin2hex(str_replace("\xC3", "", "aéb", $n)), $n, " ", bin2hex(str_ireplace("\xA9", "<>", "Éé")), " ", bin2hex(str_replace(["\xC3", "\xA9"], ["1", "2"], "é")), " ", bin2hex(str_ireplace("\xC3\xA9", "x", "\xC3\xA9\xC3")), "\n";"##;
    assert_eq!(
        run(src),
        r##"c358 61a9621 c389c33c3e 3132 78c3
"##
    );
}

#[test]
fn explode_splits_on_bytes() {
    let src = r##"<?php echo implode(",", array_map("bin2hex", explode("\xA9", "aébé"))), " ", implode(",", array_map("bin2hex", explode("\xC3", "éé", 2))), " ", implode(",", array_map("bin2hex", explode("\xC3", "éé", -1))), " ", implode(",", array_map("bin2hex", explode("\xC3", "éé", 0))), "\n";"##;
    assert_eq!(
        run(src),
        r##"61c3,62c3, ,a9c3a9 ,a9 c3a9c3a9
"##
    );
}

#[test]
fn contains_starts_and_ends_compare_bytes() {
    let src = r##"<?php var_dump(str_contains("é", "\xA9"), str_starts_with("é", "\xC3"), str_ends_with("é", "\xA9"), str_contains("\u{10FFFF}", "\xBF\xBF"));"##;
    assert_eq!(
        run(src),
        r##"bool(true)
bool(true)
bool(true)
bool(true)
"##
    );
}

#[test]
fn strstr_and_stristr_cut_at_a_byte() {
    let src = r##"<?php echo bin2hex(strstr("aéb", "\xA9")), " ", bin2hex(strstr("aéb", "\xA9", true)), " ", bin2hex(stristr("AÉB", "\x89b")), " ", var_export(stristr("é", "\xFF"), true), "\n";"##;
    assert_eq!(
        run(src),
        r##"a962 61c3 8942 false
"##
    );
}

#[test]
fn str_split_counts_bytes() {
    let src = r##"<?php echo implode(",", array_map("bin2hex", str_split("é€"))), " ", implode(",", array_map("bin2hex", str_split("a\xC3\xA9b", 3))), "\n";"##;
    assert_eq!(
        run(src),
        r##"c3,a9,e2,82,ac 61c3a9,62
"##
    );
}

#[test]
fn wordwrap_is_a_byte_port_of_the_reference() {
    let src = r##"<?php foreach ([["ééé", 2, "\n", true], ["The quick brown fox", 10, "<br>", false], ["a||b c d", 1, "||", false], ["abc def", 0, "\n", false], ["aaaa bb", 2, "|", true], ["x  y", 1, "\n", false]] as [$s, $w, $b, $c]) echo bin2hex(wordwrap($s, $w, $b, $c)), "\n";"##;
    assert_eq!(
        run(src),
        r##"c3a90ac3a90ac3a9
54686520717569636b3c62723e62726f776e20666f78
617c7c627c7c637c7c64
6162630a646566
61617c61617c6262
780a2079
"##
    );
}

#[test]
fn natural_compare_reads_bytes() {
    let src = r##"<?php var_dump(strnatcmp("é", "\xC3"), strnatcmp("\xFF", "\u{10FFFF}"), strnatcmp("a\xC3", "aé"));"##;
    assert_eq!(
        run(src),
        r##"int(1)
int(1)
int(-1)
"##
    );
}

#[test]
fn str_word_count_reads_bytes() {
    let src =
        r##"<?php var_dump(str_word_count("\x80ab \x80c", 2), str_word_count("\x80\x80a", 1));"##;
    assert_eq!(
        run(src),
        r##"array(2) {
  [1]=>
  string(2) "ab"
  [5]=>
  string(1) "c"
}
array(1) {
  [0]=>
  string(1) "a"
}
"##
    );
}

#[test]
fn str_getcsv_keeps_raw_bytes() {
    let src = r##"<?php echo implode(",", array_map("bin2hex", str_getcsv("\xC3,\xA9,\"\xFF\""))), "\n";"##;
    assert_eq!(
        run(src),
        r##"
Deprecated: str_getcsv(): the $escape parameter must be provided as its default value will change in Command line code on line 1
c3,a9,ff
"##
    );
}

#[test]
fn strripos_never_matches_a_single_high_byte() {
    let src = r##"<?php var_dump(strripos("é", "\xC3"), strripos("x\xFFy", "\xFF"), strripos("é", "\xC3\xA9"), strripos("abA", "a"));"##;
    assert_eq!(
        run(src),
        r##"bool(false)
bool(false)
int(0)
int(2)
"##
    );
}

#[test]
fn strtr_maps_a_repeated_byte_to_its_last_partner() {
    let src = r##"<?php echo strtr("aab", "aa", "xy"), " ", bin2hex(strtr("\xBF\xBF", "\xBF\xBF", "ab")), "\n";"##;
    assert_eq!(
        run(src),
        r##"yyb 6262
"##
    );
}

#[test]
fn chunk_split_of_an_empty_string_is_the_ending() {
    let src = r##"<?php var_dump(chunk_split("", 2, "|"), chunk_split("abc", 5, "|"), chunk_split("abcd", 2, "|"));"##;
    assert_eq!(
        run(src),
        r##"string(1) "|"
string(4) "abc|"
string(6) "ab|cd|"
"##
    );
}

#[test]
fn json_decode_reads_bytes_and_refuses_bad_utf8() {
    let src = r##"<?php foreach (["\"a\xFFb\"", "\"\xE2\x82\"", "[\"\xED\xA0\x80\"]", "\"\\udbff\\udfff\"", "\xFF", "\"\xF4\x8F\xBF\xBF\""] as $j) foreach ([0, JSON_INVALID_UTF8_IGNORE, JSON_INVALID_UTF8_SUBSTITUTE] as $f) { $r = json_decode($j, false, 512, $f); echo bin2hex(serialize($r)), " ", json_last_error(), "\n"; }
var_dump(json_validate("\"\xFF\""), json_last_error());"##;
    assert_eq!(
        run(src),
        r##"4e3b 5
733a323a226162223b 0
733a353a2261efbfbd62223b 0
4e3b 5
733a303a22223b 0
733a363a22efbfbdefbfbd223b 0
4e3b 5
613a313a7b693a303b733a303a22223b7d 0
613a313a7b693a303b733a393a22efbfbdefbfbdefbfbd223b7d 0
733a343a22f48fbfbf223b 0
733a343a22f48fbfbf223b 0
733a343a22f48fbfbf223b 0
4e3b 5
4e3b 5
4e3b 5
733a343a22f48fbfbf223b 0
733a343a22f48fbfbf223b 0
733a343a22f48fbfbf223b 0
bool(false)
int(5)
"##
    );
}

#[test]
fn json_encode_reads_escape_range_characters() {
    let src = r##"<?php var_dump(json_encode("\u{10FFFF}"), json_encode("x\u{10FF80}"), bin2hex(json_encode("\u{10FFFF}\xFF", JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE)), json_encode(["\u{10FFFF}" => 1]));"##;
    assert_eq!(
        run(src),
        r##"string(14) ""\udbff\udfff""
string(15) ""x\udbff\udf80""
string(18) "22f48fbfbfefbfbd22"
string(18) "{"\udbff\udfff":1}"
"##
    );
}

#[test]
fn html_functions_keep_escape_range_characters() {
    let src = r##"<?php echo bin2hex(htmlspecialchars("\u{10FFFF}<")), " ", bin2hex(htmlentities("a\u{10FF80}")), " ", bin2hex(html_entity_decode("&#x10FFFF;&#xE9;")), " ", bin2hex(htmlspecialchars_decode("&#x10FFFF;")), "\n";"##;
    assert_eq!(
        run(src),
        r##"f48fbfbf266c743b 61f48fbe80 f48fbfbfc3a9 2623783130464646463b
"##
    );
}

#[test]
fn mb_functions_keep_escape_range_characters() {
    let src = r##"<?php echo bin2hex(mb_chr(0x10FFFF)), " ", mb_strlen("\u{10FFFF}"), " ", bin2hex(mb_substr("a\u{10FFFF}b", 1, 1)), " ", bin2hex(mb_strtoupper("\u{10FFFF}a")), " ", bin2hex(mb_convert_case("\u{10FFFF}", MB_CASE_TITLE)), " ", mb_strwidth("\u{10FFFF}"), " ", implode(",", array_map("bin2hex", mb_str_split("\u{10FFFF}é"))), " ", bin2hex(mb_str_pad("\u{10FFFF}", 3, "*")), " ", var_export(mb_check_encoding("\u{10FFFF}"), true), " ", bin2hex(mb_decode_numericentity("&#x10FFFF;", [0, 0x10FFFF, 0, 0x1FFFFF])), "\n";"##;
    assert_eq!(
        run(src),
        r##"f48fbfbf 1 f48fbfbf f48fbfbf41 f48fbfbf 1 f48fbfbf,c3a9 f48fbfbf2a2a true f48fbfbf
"##
    );
}

#[test]
fn mb_split_and_pad_copy_invalid_sequences_through() {
    let src = r##"<?php echo implode(",", array_map("bin2hex", mb_str_split("\xFFa\xE2\x82"))), " ", bin2hex(mb_str_pad("\xFF", 3, "*")), " ", bin2hex(mb_str_pad("a", 4, "\xC3", STR_PAD_LEFT)), " ", bin2hex(mb_ucfirst("\xFFa")), " ", bin2hex(mb_scrub("a\xE2\x82\xFF")), " ", bin2hex(mb_strimwidth("\xFFabc", 0, 3, ".")), "\n";"##;
    assert_eq!(
        run(src),
        r##"ff,61,e282 ff2a2a c3c3c361 ff61 613f3f 3f612e
"##
    );
}

#[test]
fn mb_strpos_searches_bytes() {
    let src = r##"<?php var_dump(mb_strpos("é", "\xC3"), mb_strpos("é", "\xA9"), mb_strpos("a\x80b", "b"), mb_strrpos("éaé", "\xA9"), mb_strrpos("aXbX", "X", -2), mb_strrpos("aXbX", "X", -1), mb_strpos("aéb", "b", 2));
try { mb_strpos("ab", "a", 3); } catch (ValueError $e) { echo $e->getMessage(), "\n"; }"##;
    assert_eq!(
        run(src),
        r##"int(0)
int(1)
int(1)
int(3)
int(1)
int(3)
int(2)
mb_strpos(): Argument #3 ($offset) must be contained in argument #1 ($haystack)
"##
    );
}

#[test]
fn mb_ord_of_an_invalid_sequence_is_false() {
    let src = r##"<?php var_dump(mb_ord("\xC3"), mb_ord("\u{10FFFF}"), mb_ord("é"));"##;
    assert_eq!(
        run(src),
        r##"bool(false)
int(1114111)
int(233)
"##
    );
}

#[test]
fn a_pattern_byte_matches_that_byte() {
    let src = r##"<?php var_dump(preg_match("/\xC3/", "é"), preg_match("/[\xA9]/", "é"), preg_replace("/\xA9/", "X", "é") === "\xC3X", bin2hex(implode("|", preg_split("/\xC3/", "aéb"))), preg_match("/\u{10FFFF}/", "\u{10FFFF}"), preg_replace("/\x{10FFFF}/u", "X", "a\u{10FFFF}"), preg_match("/^.$/u", "\u{10FFFF}"));"##;
    assert_eq!(
        run(src),
        r##"int(1)
int(1)
bool(true)
string(8) "617ca962"
int(1)
string(2) "aX"
int(1)
"##
    );
}

#[test]
fn a_u_pattern_that_is_not_utf8_is_refused() {
    let src = r##"<?php foreach (["/a\xFFb/u", "/\xC3/u", "/\xE2\x82/u", "/\x80/u", "/\xED\xA0\x80/u", "/\xC0\x80/u", "/\xF4\x90\x80\x80/u", "/\xF8\x88\x80\x80\x80/u"] as $p) { var_dump(preg_match($p, "x")); echo preg_last_error(), "\n"; }"##;
    assert_eq!(
        run(src),
        r##"
Warning: preg_match(): Compilation failed: UTF-8 error: illegal byte (0xfe or 0xff) at offset 1 in Command line code on line 1
bool(false)
1

Warning: preg_match(): Compilation failed: UTF-8 error: 1 byte missing at end at offset 0 in Command line code on line 1
bool(false)
1

Warning: preg_match(): Compilation failed: UTF-8 error: 1 byte missing at end at offset 0 in Command line code on line 1
bool(false)
1

Warning: preg_match(): Compilation failed: UTF-8 error: isolated byte with 0x80 bit set at offset 0 in Command line code on line 1
bool(false)
1

Warning: preg_match(): Compilation failed: UTF-8 error: code points 0xd800-0xdfff are not defined at offset 0 in Command line code on line 1
bool(false)
1

Warning: preg_match(): Compilation failed: UTF-8 error: overlong 2-byte sequence at offset 0 in Command line code on line 1
bool(false)
1

Warning: preg_match(): Compilation failed: UTF-8 error: code points greater than 0x10ffff are not defined at offset 0 in Command line code on line 1
bool(false)
1

Warning: preg_match(): Compilation failed: UTF-8 error: 5-byte character is not allowed (RFC 3629) at offset 0 in Command line code on line 1
bool(false)
1
"##
    );
}

#[test]
fn pcre_punctuation_and_octal_escapes() {
    let src = r##"<?php var_dump(preg_match_all("/\\</", "a<b<"), preg_match_all("/\\>/", ">>"), preg_match("/\\000/", "a\0"), preg_match("/\\07x/", "\x07x"), preg_replace("/" . preg_quote("<a>\0") . "/", "#", "x<a>\0y"));"##;
    assert_eq!(
        run(src),
        r##"int(2)
int(2)
int(1)
int(1)
string(3) "x#y"
"##
    );
}

#[test]
fn string_comparison_orders_bytes() {
    let src = r##"<?php $a = ["\xFF", "\u{10FFFF}", "é", "\xC3"]; sort($a); echo implode(",", array_map("bin2hex", $a)), " "; $b = $a; rsort($b, SORT_STRING); echo implode(",", array_map("bin2hex", $b)), " "; var_dump("\xC3" < "é", strcmp("\xC3", "é") < 0);"##;
    assert_eq!(
        run(src),
        r##"c3,c3a9,f48fbfbf,ff ff,f48fbfbf,c3a9,c3 bool(true)
bool(true)
"##
    );
}

#[test]
fn vfprintf_writes_bytes() {
    let src = r##"<?php $h = fopen("php://memory", "w+"); vfprintf($h, "%s|%s", ["\xFF", "\u{10FFFF}"]); rewind($h); echo bin2hex(stream_get_contents($h)), "\n";"##;
    assert_eq!(
        run(src),
        r##"ff7cf48fbfbf
"##
    );
}
